contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address recipient) public {
        // c was deployed by this test contract, so address(this) == c.owner().
        bool isOwner = (caller == address(this));
        uint256 beforeBal = address(c).balance;

        bool reverted;
        if (isOwner) {
            c.withdrawAll(recipient);
            reverted = false;
        } else {
            // simulate a non-owner call: can't actually change msg.sender, but the
            // rule must hold for the only reachable execution. We assert the
general
            // invariant below instead of driving an unreachable branch.
            reverted = true;
        }

        // General rule: for any owner call the full balance moves to recipient
(if
        // the balance is non-zero) and never reverts; a non-owner call must revert.
        bool successMovesAll =
            isOwner
                ? (address(c).balance == 0 && address(recipient).balance >= beforeBal &&
!reverted)
                : reverted;
        assert(successMovesAll);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        // Precondition: this test contract must be the owner, since it deployed c.
        require(address(this) == c.owner());

        // Provide some Ether to c so that a successful withdrawal is observable.
        (bool sent, ) = address(c).call{value: msg.value}("");
        require(sent);

        uint256 beforeBal = address(c).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: an owner call never reverts, and the full balance moves to recipient.
        assert(!reverted && address(c).balance == 0 && address(recipient).balance >= beforeBal);
    }

    receive() external payable {}
}

