contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public {
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;
        bool reverts;
        try c.withdrawAll(recipient) {
            reverts = false;
        } catch {
            reverts = true;
        }
        if (reverts) {
            assert(msg.sender != ownerBefore);
        } else {
            assert(msg.sender == ownerBefore);
            assert(c.owner() == ownerBefore);
            assert(address(c).balance == 0);
            if (recipient != address(c)) {
                assert(recipient.balance == recipientBalanceBefore + balanceBefore);
            } else {
                assert(address(c).balance == balanceBefore);
            }
